import zipfile


class ZipFileProcessor:
    ZIP_MODE_READ = 'r'
    ZIP_MODE_WRITE = 'w'

    def __init__(self, file_name):
        self._file_name = file_name

    @property
    def file_name(self):
        return self._file_name

    @file_name.setter
    def file_name(self, value):
        self._file_name = value

    def _open_zip_file_for_reading(self):
        try:
            return zipfile.ZipFile(self._file_name, self.ZIP_MODE_READ)
        except (OSError, zipfile.BadZipFile):
            return None

    def read_zip_file(self):
        return self._open_zip_file_for_reading()

    def _extract_to_path(self, zip_file, output_path, file_name=None):
        if file_name is None:
            zip_file.extractall(output_path)
        else:
            zip_file.extract(file_name, output_path)

    def extract_all(self, output_path):
        try:
            with zipfile.ZipFile(self._file_name, self.ZIP_MODE_READ) as zip_file:
                self._extract_to_path(zip_file, output_path)
            return True
        except (OSError, zipfile.BadZipFile):
            return False

    def extract_file(self, file_name, output_path):
        try:
            with zipfile.ZipFile(self._file_name, self.ZIP_MODE_READ) as zip_file:
                self._extract_to_path(zip_file, output_path, file_name)
            return True
        except (OSError, zipfile.BadZipFile):
            return False

    def _create_and_write_files(self, output_file_name, files):
        with zipfile.ZipFile(output_file_name, self.ZIP_MODE_WRITE) as zip_file:
            for file in files:
                zip_file.write(file)

    def create_zip_file(self, files, output_file_name):
        try:
            self._create_and_write_files(output_file_name, files)
            return True
        except (OSError, zipfile.BadZipFile):
            return False
